#include <stdlib.h>

typedef struct Node { int val; struct Node *next; } Node;
typedef struct { Node *head, *tail; size_t size; } Queue;

void q_init(Queue *q) { q->head = q->tail = NULL; q->size = 0; }

int enqueue(Queue *q, int x) {
    Node *n = malloc(sizeof *n);
    if (!n) return -1;
    n->val = x; n->next = NULL;
    if (q->tail) q->tail->next = n;
    else         q->head = n;        /* first element */
    q->tail = n;
    q->size++;
    return 0;
}

int dequeue(Queue *q, int *out) {
    if (!q->head) return -1;         /* underflow */
    Node *t = q->head;
    *out = t->val;
    q->head = t->next;
    if (!q->head) q->tail = NULL;    /* became empty */
    free(t);
    q->size--;
    return 0;
}

void bfs(int n, int adj[][MAXN], int start) {
    int q[MAXN], head = 0, tail = 0;
    int seen[MAXN] = {0};
    q[tail++] = start; seen[start] = 1;
    while (head < tail) {
        int u = q[head++];
        for (int v = 0; v < n; v++)
            if (adj[u][v] && !seen[v]) {
                seen[v] = 1;
                q[tail++] = v;     /* each node enqueued once */
            }
    }
}
